97	func (h *MetricHistory) GetStats(now time.Time) WindowStats {
98		h.mu.RLock()
99		defer h.mu.RUnlock()
100	
101		if len(h.history) == 0 {
102			return WindowStats{
103				DataPoints:  0,
104				LastUpdate:  now,
105				WindowStart: now.Add(-h.maxAge),
106				WindowEnd:   now,
107			}
108		}
109	
110		// Calculate statistics
111		var sum, min, max float64
112		min = math.MaxFloat64
113		max = -math.MaxFloat64
114	
115		for _, point := range h.history {
116			sum += point.Value
117			if point.Value < min {
118				min = point.Value
119			}
120			if point.Value > max {
121				max = point.Value
122			}
123		}
124	
125		mean := sum / float64(len(h.history))
126	
127		// Calculate variance
128		var varianceSum float64
129		for _, point := range h.history {
130			diff := point.Value - mean
131			varianceSum += diff * diff
132		}
133		variance := varianceSum / float64(len(h.history))
134		stdDev := math.Sqrt(variance)
135	
136		return WindowStats{
137			DataPoints:  len(h.history),
138			Mean:        mean,
139			Variance:    variance,
140			StdDev:      stdDev,
141			Min:         min,
142			Max:         max,
143			LastUpdate:  now,
144			WindowStart: h.history[0].Timestamp,
145			WindowEnd:   h.history[len(h.history)-1].Timestamp,
146		}
147	}
