150	type TimeWindow struct {
151		mu          sync.RWMutex
152		duration    time.Duration
153		granularity time.Duration
154		buckets     map[int64]float64
155		values      []float64
156	}
157	
158	// NewTimeWindow creates a new time window
159	func NewTimeWindow(duration, granularity time.Duration) *TimeWindow {
160		return &TimeWindow{
161			duration:    duration,
162			granularity: granularity,
163			buckets:     make(map[int64]float64),
164			values:      make([]float64, 0),
165		}
166	}
